import { defineConfig } from "vite";

/**
 * Vite config for the MASRA one-pager.
 *
 * The site is fully static: one HTML entry, TS modules, and pre-optimized
 * images living in /public/images (generated by scripts/optimize-images.mjs,
 * never processed by Vite). Build output (dist/) deploys to Cloudflare Pages.
 */
export default defineConfig({
  build: {
    // Keep asset filenames hashed (default) so public/_headers can cache
    // /assets/* as immutable on Cloudflare Pages.
    target: "es2022",
  },
  server: {
    port: 5173,
    strictPort: true,
  },
});
